// The screening ruleset. models.py and screen.py, in one node.
//
// This is a sub-workflow rather than a Code node inside the pipeline for one
// reason, and it is the reason the whole eval means anything: the evaluation
// workflow calls THIS, not a copy of it. A ruleset that is pasted into both
// the pipeline and the eval scores 100% on the day you write it and then
// silently measures the wrong code from the first time somebody edits one
// and not the other. An eval that grades a copy is theatre.
//
// The node is a pure function -- no HTTP, no database, no clock, no $env. It
// reads its thresholds from _config on the incoming item, which the caller
// loaded from the config table. That is what makes it testable against a
// golden set at all, and it is why the eval can state exactly which
// thresholds produced a given score.

const RULESET_VERSION = 'v3-two-thresholds';
const ALLOWED = ['youtube', 'tiktok', 'instagram'];

// Defaults matter here. If the caller forgets _config the node must not
// silently screen everybody against NaN, which compares false against every
// threshold and would accept the entire intake.
const cfg = $input.first()?.json?._config ?? {};
const MIN_FOLLOWERS = Number(cfg.min_followers ?? 5000);
const REVIEW_FOLLOWERS = Number(cfg.review_followers ?? 20000);

if (!Number.isFinite(MIN_FOLLOWERS) || !Number.isFinite(REVIEW_FOLLOWERS)) {
  throw new Error(`thresholds are not numbers: ${JSON.stringify(cfg)}`);
}
if (MIN_FOLLOWERS > REVIEW_FOLLOWERS) {
  // Inverted thresholds make the review band empty and send everybody to one
  // of the two extremes. Cheap to check, and invisible if you do not.
  throw new Error(`min_followers ${MIN_FOLLOWERS} is above review_followers ${REVIEW_FOLLOWERS}`);
}

// A tracking code derived from the application id, never random.
//
// Random would be a different code on every retry, so an execution that died
// after creating the creator but before sending the email would, on replay,
// either create a second creator or send a code that does not match the
// stored one. A pure function of the input has neither problem.
//
// FNV-1a twice, with different offset bases, for 64 bits. Written out rather
// than require('crypto') because Code nodes run in a task runner that does
// not allow builtins unless the instance is configured for it -- and that is
// an instance-wide setting to change for one hash. Not a cryptographic
// requirement: this only has to be deterministic and spread out. At 64 bits,
// ten thousand creators collide with probability around 3e-12, and a
// collision would fail the UNIQUE constraint rather than pay the wrong
// person.
function trackingCode(s) {
  const fnv = (seed) => {
    let h = seed;
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 0x01000193) >>> 0;
    }
    return h.toString(16).toUpperCase().padStart(8, '0');
  };
  return `CP-${fnv(0x811c9dc5)}${fnv(0x9dc5811c)}`;
}

const out = [];

for (const item of $input.all()) {
  const { _config, ...a } = item.json;
  const errors = [];

  // Normalise first, validate second. '@Ana' and 'ana' are the same person,
  // and ' YouTube ' is the same platform: normalising on the way in means
  // every later comparison is a plain string equality instead of every call
  // site remembering to strip.
  const external_id = String(a.external_id ?? '').trim();
  const email = String(a.email ?? '').trim().toLowerCase();
  const handle = String(a.handle ?? '').trim().replace(/^@/, '');
  const platform = String(a.platform ?? '').trim().toLowerCase();
  const followers = a.followers;

  if (!external_id) errors.push('external_id is required');
  if (!email || !email.includes('@')) errors.push('email is not valid');
  if (!handle) errors.push('handle is required');
  if (!ALLOWED.includes(platform)) {
    // Rejected here rather than later because the tracker has no way to look
    // for posts on an unknown platform, so accepting this applicant would
    // create a creator who can never be paid.
    errors.push(`unsupported platform '${platform}', expected one of ${ALLOWED.join(', ')}`);
  }
  if (!Number.isInteger(followers) || followers < 0) {
    errors.push('followers must be a non-negative integer');
  }

  if (errors.length) {
    // Invalid is a decision, not a crash. A malformed application is data;
    // throwing here would fail the whole batch over one bad row.
    out.push({ json: { ...a, valid: false, decision: 'invalid',
      reason: errors.join('; '), ruleset_version: RULESET_VERSION } });
    continue;
  }

  // Three outcomes, not two. Collapsing 'review' into 'accepted' onboards
  // people nobody looked at; collapsing it into 'rejected' throws away the
  // applicants most worth a conversation.
  let decision, reason;
  if (followers < MIN_FOLLOWERS) {
    decision = 'rejected';
    reason = `${followers} followers, below the ${MIN_FOLLOWERS} minimum`;
  } else if (followers < REVIEW_FOLLOWERS) {
    decision = 'review';
    reason = `${followers} followers, between the automatic thresholds`;
  } else {
    decision = 'accepted';
    reason = `${followers} followers, above ${REVIEW_FOLLOWERS}`;
  }

  out.push({ json: { ...a, external_id, email, handle, platform, followers,
    valid: true, decision, reason, tracking_code: trackingCode(external_id),
    ruleset_version: RULESET_VERSION,
    thresholds: { min_followers: MIN_FOLLOWERS, review_followers: REVIEW_FOLLOWERS } } });
}

return out;
